from pathlib import Path
p = Path("fastapi/exceptions.py")
old = r'''
class ValidationException(Exception):
    def __init__(self, errors: Sequence[Any]) -> None:
        self._errors = errors

    def errors(self) -> Sequence[Any]:
        return self._errors


class RequestValidationError(ValidationException):
    def __init__(self, errors: Sequence[Any], *, body: Any = None) -> None:
        super().__init__(errors)
        self.body = body

'''
new = r'''
class ValidationException(Exception):
    def __init__(self, errors: Sequence[Any], endpoint_context: Optional[str] = None) -> None:
        self._errors = errors
        self.endpoint_context = endpoint_context

    def errors(self) -> Sequence[Any]:
        return self._errors

    def __str__(self) -> str:
        message = f"{len(self._errors)} validation errors:\n"
        for err in self._errors:
            message += f"  {err}\n"
        if self.endpoint_context:
            message += f"\n{self.endpoint_context}"
        return message


class RequestValidationError(ValidationException):
    def __init__(
        self, errors: Sequence[Any], *, body: Any = None, endpoint_context: Optional[str] = None
    ) -> None:
        super().__init__(errors, endpoint_context=endpoint_context)
        self.body = body

'''
s = p.read_bytes().decode()
assert s.count(old) == 1, s.count(old)
s = s.replace(old, new)
if p.suffix == ".py":
    compile(s, str(p), "exec")
p.write_bytes(s.encode())
print("edited", p)
